insert into "monthly_market_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-05-01', 'มุมมองตลาดเดือนพฤษภาคม 2569: Overweight หุ้นโลก ท่ามกลางแรงส่ง AI Capex และความเสี่ยง Stagflation ที่ยังจำกัด', '2026-05-01', 'มุมมองตลาดเดือนพฤษภาคม 2569: Overweight หุ้นโลก ท่ามกลางแรงส่ง AI Capex และความเสี่ยง Stagflation ที่ยังจำกัด', 'มุมมองการลงทุนรายเดือนโดย Yuanta CIO พฤษภาคม 2569', '2026-05-01', '2026-05-01', '2026-05-31', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_images/page_005.png?v=20260617", "altText": "", "type": "image"}'::jsonb, 'แรงส่งฤดูกาลรายงานผลประกอบการเริ่มจาง ปัจจัยมหภาคและ AI Capex เข้ามาเป็นตัวแปรสำคัญ — พฤษภาคมนี้ Yuanta CIO ชี้โอกาสสะสมเมื่อตลาดอ่อนตัว', '<p><span>ตลาดหุ้นโลกฟื้นตัวราว 10% ในเดือนเมษายน นำโดยกลุ่มเทคโนโลยีและ AI supply chain หลังความตึงเครียดภูมิรัฐศาสตร์ผ่อนคลาย</span></p><p><span>เดือนพฤษภาคม Yuanta CIO แนะนำ Overweight ตราสารทุน โดยเฉพาะ KOSPI และ NASDAQ พร้อมสะสมเพิ่มเมื่อตลาดปรับฐานจากความกังวล Stagflation</span></p>', '<h3><span>ภาพรวมตลาดการเงินโลก</span></h3><p><span>เข้าสู่เดือนพฤษภาคม 2569 ตลาดการเงินโลกเพิ่งผ่านพ้นช่วงฟื้นตัวที่มีนัยสำคัญในเดือนเมษายน โดยดัชนีหุ้นโลก (ACWI) ปรับตัวขึ้นมาราว 10% จากจุดต่ำสุด หลังสถานการณ์ความขัดแย้งระหว่างอิหร่านและสหรัฐฯ มีพัฒนาการด้านการเจรจาในเชิงบวก แม้จะเป็นเพียงการหยุดยิงชั่วคราวก็ตาม ตลาดที่นำการฟื้นตัว ได้แก่ เกาหลีใต้ ไต้หวัน ญี่ปุ่น และสหรัฐฯ โดยเฉพาะกลุ่มเทคโนโลยีและ Growth sector ขณะที่ผลประกอบการ 1Q26 ออกมาดีกว่าคาดในหลายกลุ่ม นำโดยเทคโนโลยีและวัตถุดิบ</span></p><p><span>อย่างไรก็ดี ในเดือนพฤษภาคม แรงส่งจากฤดูกาลรายงานผลประกอบการจะเริ่มจางลง และปัจจัยด้านมหภาคจะเข้ามามีบทบาทมากขึ้น โดยเฉพาะความกังวลด้าน Stagflation อันเป็นผลจากราคาน้ำมันที่ยังอยู่ในระดับสูง (WTI ที่ 96 ดอลลาร์) Yuanta CIO ประเมินว่าโอกาสเกิด Stagflation ในสหรัฐฯ ยังอยู่ในระดับต่ำ โดยตราบใดที่ตัวเลข CPI ยังไม่แตะระดับ 4–5% ยังไม่ถือเป็นสัญญาณที่น่ากังวล และยังคงแนะนำให้ใช้จังหวะที่ตลาดอ่อนตัวเป็นโอกาสเข้าสะสม</span></p><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_images/page_003.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Wealth Signal Asset Class Weighting May 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p>&nbsp;</p><h3><span>สรุปจุดยืนแต่ละสินทรัพย์ (Cross-Asset Stance)</span></h3><p><span>Yuanta CIO สรุปมุมมองเชิงกลยุทธ์รายสินทรัพย์ ณ สิ้นเดือนเมษายน 2569 ดังตารางต่อไปนี้ โดยใช้ข้อมูล ณ วันที่ 28 เมษายน 2569 เป็นฐาน</span></p><div data-hs-responsive-table=''true'' style=''overflow-x: auto; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''><table style=''width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #99acc2;''><tbody><tr><td style=''padding: 6px 8px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>สินทรัพย์</span></td><td style=''padding: 6px 8px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>จุดยืน</span></td><td style=''padding: 6px 8px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>เหตุผลหลัก</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นโลก (ACWI)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Overweight</span></td><td style=''padding: 6px 8px;''><span>กำไร 12 เดือนข้างหน้าแข็งแกร่ง LT Return 7.77% Upside 12% — ใช้ ACWI ETF เป็น Core</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นสหรัฐฯ (S&P 500 / NASDAQ)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Overweight</span></td><td style=''padding: 6px 8px;''><span>NASDAQ LT Return 12.34% Upside 18% Reward/Risk 2.36x — AI-driven earnings จาก Cloud, Search, Ads และ Enterprise AI ยังหนุนแรง</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นยุโรป (STOXX 600)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span></td><td style=''padding: 6px 8px;''><span>Upside จำกัดที่ 5% Reward/Risk 0.37x ความเสี่ยง Stagflation ระดับกลาง-สูง ECB มีแนวโน้มขึ้นดอกเบี้ยถึง 2.5%</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นญี่ปุ่น (TOPIX)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span></td><td style=''padding: 6px 8px;''><span>Upside 10% Reward/Risk 1.26x BOJ มีแนวโน้มขึ้นดอกเบี้ยแตะ 1.25% ในปี 2026 — ได้ประโยชน์จาก semiconductor supply chain</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นจีน (MSCI China / CSI300 / HSCEI)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Underweight</span></td><td style=''padding: 6px 8px;''><span>CSI 300 และ HSCEI มี Reward/Risk ติดลบ Downside สูงถึง 22–25% ค่าเป้าหมายต่ำกว่าราคาปัจจุบัน</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นเกาหลีใต้ (KOSPI)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Overweight</span></td><td style=''padding: 6px 8px;''><span>Reward/Risk สูงสุดในกลุ่มที่ 7.43x Upside 36% เป้า 7,519 (Bull 9,023) — AI semiconductor supply chain เป็นตัวเร่งหลัก</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นอินเดีย (NIFTY50)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span></td><td style=''padding: 6px 8px;''><span>LT Return 11.29% สูงสุดอันดับ 2 Upside 8% Reward/Risk 1.22x — Quality Growth ในตลาดเกิดใหม่</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นไทย (SET)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Underweight</span></td><td style=''padding: 6px 8px;''><span>Upside 0% Reward/Risk 0.00x เป้าหมาย Bull = ราคาปัจจุบัน 1,480 จุด ศักยภาพกำไรต่ำกว่าตลาดอื่น</span></td></tr><tr><td style=''padding: 6px 8px;''><span>หุ้นเวียดนาม (VNI)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Underweight</span></td><td style=''padding: 6px 8px;''><span>Downside สูงถึง 21% Reward/Risk 0.14x แม้ LT Return 7.68% แต่ Repricing Factor เป็นแรงฉุดในระยะสั้น</span></td></tr><tr><td style=''padding: 6px 8px;''><span>พันธบัตรสหรัฐฯ (US 10Y)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span></td><td style=''padding: 6px 8px;''><span>Yield ปัจจุบัน 4.30% เป้าหมาย 4.17% Fed มีแนวโน้มตรึงดอกเบี้ยที่ 3.75% ถึงปี 2027 — ไม่คาดเห็นการลดดอกเบี้ยเร็ว</span></td></tr><tr><td style=''padding: 6px 8px;''><span>พันธบัตรไทย (TH 10Y)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Underweight</span></td><td style=''padding: 6px 8px;''><span>Yield ปัจจุบัน 2.10% LT Return 1.85% ให้ผลตอบแทนต่ำกว่าตราสารทุน — ลด Duration เพื่อเน้น Cash-Equity</span></td></tr><tr><td style=''padding: 6px 8px;''><span>ทองคำ (XAUUSD)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span></td><td style=''padding: 6px 8px;''><span>ราคาปัจจุบัน 4,719 เป้า 4,786 Upside 10% Bull 5,205 — ทำหน้าที่ Diversifying &amp; Hedge Asset แต่ Reward/Risk 0.94x</span></td></tr><tr><td style=''padding: 6px 8px;''><span>น้ำมัน (WTI)</span></td><td style=''padding: 6px 8px; text-align: center;''><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Underweight</span></td><td style=''padding: 6px 8px;''><span>WTI ที่ 96 ดอลลาร์ มี Downside สูงถึง 47% เป้า Base Case 66.49 Reward/Risk ติดลบ -0.32x</span></td></tr></tbody></table></div><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_images/page_005.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Cross-Asset Expected Return and Target Forecast'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p>&nbsp;</p><h3><span>Capital Market Expectation: ผลตอบแทนระยะยาวคาดหวัง</span></h3><p><span>แบบจำลอง Capital Market Expectation (CME) ของ Yuanta CIO แยกย่อยผลตอบแทนระยะยาวออกเป็น 4 องค์ประกอบ ได้แก่ Risk Free, Inflation Premium, Repricing Factor และ Growth โดยในเดือนนี้ CME โดยรวมปรับตัวลดลงเล็กน้อยจากการฟื้นตัวของราคาหุ้นที่ดีดขึ้นมาในเดือนเมษายน ทำให้ Valuation ตึงตัวขึ้น จุดที่ Yuanta CIO ให้ความสนใจในระยะ 1–2 เดือนข้างหน้าคือการปรับมุมมองกำไรตลาด (Growth component สีฟ้า) ซึ่งจะเป็นปัจจัยกำหนดว่าตลาดใดจะรักษา LT Expected Return เหนือระดับ 5% ได้ต่อเนื่อง NASDAQ และ NIFTY50 ยังคงโดดเด่นด้วย LT Return ที่ 12.34% และ 11.29% ตามลำดับ ขณะที่ KOSPI มี Growth component ขนาดใหญ่เป็นพิเศษ สะท้อนศักยภาพที่ยังไม่ถูก Price in อย่างเต็มที่</span></p><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_images/page_006.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Cross-Asset LT Expected Return Components May 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p>&nbsp;</p><h3><span>กลยุทธ์จัดพอร์ตการลงทุนเดือนนี้</span></h3><p><span>Yuanta CIO แนะนำใช้กลยุทธ์ Core-Satellite เป็นกรอบหลักในเดือนพฤษภาคม โดย Core Portfolio เน้นสะสมตราสารทุนโลกผ่าน ACWI อย่างต่อเนื่อง ขณะที่ Satellite Portfolio มุ่งเน้นโอกาสเชิงกลยุทธ์ใน KOSPI และ NASDAQ ซึ่งมี Reward/Risk สูงสุดในกลุ่ม สำหรับตราสารหนี้ แนะนำลดน้ำหนักพันธบัตรไทยและไม่รีบ Add Duration ใน US Bond จนกว่า Fed จะส่งสัญญาณลดดอกเบี้ยชัดเจนขึ้น กลยุทธ์โดยรวมยังคงเป็น Cash-Equity เนื่องจากความสัมพันธ์ระหว่างสินทรัพย์ (Correlation) ที่ปรับตัวสูงขึ้นทำให้การกระจายความเสี่ยงแบบ Multi-Asset ทำได้จำกัดในระยะสั้น</span></p><ul><li><span>Core Portfolio: เพิ่มน้ำหนัก ACWI ETF ทยอยสะสมเมื่อตลาดปรับฐาน โดยเฉพาะเมื่อ ACWI ย่อลงมาในโซน 1,000–1,040</span></li><li><span>Satellite — AI &amp; Semiconductor: เพิ่มน้ำหนัก KOSPI (เป้า 7,519 / Bull 9,023) และ NASDAQ ผ่านธีม AI investment และ Semiconductor supply chain — ได้แก่ กลุ่ม Power &amp; Cooling infrastructure และ Memory</span></li><li><span>Satellite — Quality Growth: NIFTY50 เป็น Slightly Overweight รองรับ Quality Growth ในตลาดเกิดใหม่ที่ LT Return 11.29%</span></li><li><span>Hedge: คงน้ำหนักทองคำ (XAUUSD) ไว้ในระดับ Neutral เป็น Diversifying &amp; Hedge Asset รับมือความผันผวนด้านภูมิรัฐศาสตร์ในช่วงที่ตลาดกังวล Stagflation</span></li><li><span>ลด/หลีกเลี่ยง: ลดน้ำหนัก CSI 300, HSCEI, SET, VNI, พันธบัตรไทย และ WTI — Reward/Risk ไม่คุ้มค่าเมื่อเทียบกับโอกาสในตลาดหุ้นพัฒนาแล้ว</span></li></ul><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/component_images/page_43.jpg?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Core-Satellite Portfolio Strategy Overview'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>');
insert into "monthly_market_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-06-01', 'มุมมองตลาดเดือนมิถุนายน 2569: Selective Overweight หุ้นโลก เน้น AI Supply Chain ลดน้ำหนักหุ้นไทย และรับมือ Bear Flattening', '2026-06-01', 'มุมมองตลาดเดือนมิถุนายน 2569: Selective Overweight หุ้นโลก เน้น AI Supply Chain ลดน้ำหนักหุ้นไทย และรับมือ Bear Flattening', 'มุมมองการลงทุนรายเดือนโดย Yuanta CIO มิถุนายน 2569', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'เดือนมิถุนายนมาพร้อมสัญญาณ Selective Buy ใน AI Ecosystem ขณะที่หุ้นไทยถูกปรับลด และ Bear Flattening กำลังเดินทางมาถึง — Yuanta CIO เผยกลยุทธ์รับมือทุกสถานการณ์', '<p><span>ตลาดหุ้นโลกเดือนพฤษภาคมปรับขึ้นราว 5% นำโดยกลุ่ม AI และ Semiconductor ขณะที่เดือนมิถุนายน Yuanta CIO แนะ Selective Buy on Weakness ในกลุ่ม AI พร้อมลดน้ำหนักหุ้นไทยสู่ระดับ Neutral และเพิ่ม Software เพื่อกระจายความเสี่ยงรับมือ Bear Flattening</span></p>', '<h3><span>ภาพรวมตลาดการเงินโลก</span></h3>
<p><span>เดือนมิถุนายน 2569 เริ่มต้นท่ามกลางบรรยากาศ Risk-On ที่สืบเนื่องจากเดือนพฤษภาคม ซึ่ง Global Equities ปรับขึ้นราว 5% โดยมีแรงนำจากผลประกอบการกลุ่ม Semiconductor และ AI Chip ที่แข็งแกร่งกว่าตลาดคาด S&P 500 ปรับขึ้น 5.15% ปิดเหนือ 7,500 จุด และทำ All-Time High ต่อเนื่อง ขณะที่ Nasdaq Outperform จากกลุ่ม Technology ส่วนตลาดเอเชียเหนืออย่าง KOSPI, TWSE และ Nikkei 225 โดดเด่นตามธีม AI Supply Chain และ CPU ที่ฟื้นตัวกลับขึ้นมา ด้าน US Oil ปรับลงเกือบ 17% และ Commodity ลดลงราว 4% หลังสถานการณ์ระหว่างสหรัฐฯ กับอิหร่านไม่รุนแรงขึ้น Dollar Index กลับมาแข็งค่าเล็กน้อย และ US Bond Yield ขยับขึ้นทั้ง Curve สะท้อนความกังวลด้านเงินเฟ้อที่อาจกดดันให้ Fed ไม่สามารถลดดอกเบี้ยได้ตามแผนเดิม</span></p>
<p><span>ประเด็นมหภาคสำคัญในเดือนนี้คือการประชุม Fed เดือนมิถุนายน ซึ่งจะเป็นบทพิสูจน์ "4 Warsh Problems" ได้แก่ เงินเฟ้อและ Credibility ของ Fed, ความเป็นอิสระของ Fed, การสื่อสารกับตลาด และ Balance Sheet Normalization ตลาดต้องติดตามว่า Warsh จะส่งสัญญาณนำ Trimmed Mean PCE เข้ามาใช้ในการพิจารณาแนวทางดอกเบี้ยมากขึ้นหรือไม่ เพราะอาจช่วยแยกเงินเฟ้อจาก Energy, Tariff และ Supply Shock ออกจากเงินเฟ้อพื้นฐาน ทำให้ตลาดมอง Path ดอกเบี้ยได้ยืดหยุ่นขึ้น อย่างไรก็ดี ในระยะสั้นนักลงทุนต้องเตรียมรับมือภาวะ Bear Flattening ที่กำลังเข้ามาถึงในช่วงต่อจากนี้</span></p>
<p><span>ด้านจุลภาค Earnings Momentum ยังแข็งแกร่งในกลุ่ม Technology โดย S&P 500 รายงานงบ 1Q26 ส่วนใหญ่ดีกว่าคาด และ EPS Estimate ไตรมาส 2 ถูกปรับขึ้นสวนทาง Seasonality ตัวเร่งที่ต้องจับตาในเดือนมิถุนายนได้แก่ COMPUTEX, GTC Taipei, รายได้รายเดือนของ TSMC และ Hon Hai, ตัวเลขส่งออกเกาหลีใต้และไต้หวัน รวมถึงงบของ Broadcom, Oracle และ Micron</span></p>
